; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: cpc (Amstrad CPC - direct hardware, no firmware), starts in normal mode
; ============================================================

			org #0040

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 40		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 0		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)
NTC_WINHOLE	equ 0		; 1 = the program is built round an Option Reserve range over the window #4000-#7FFF
NTC_BUFSIZE	equ 2048		; the library's buffer (ntc_buf: FileSystem, Memory.Copy): Option Buffer
NTC_CPMGFX	equ 0		; 1 = CP/M: Graphics draws on an Amstrad CPC's screen (2.2: #C000, Plus: block 1 from common memory)

ntc_start:
			jr ntc_start2
ntc_bk_sp:		dw 0			; #0042: main RAM's SP while a bank runs
ntc_bk_out:
			out (c), c		; #0044: BC = the other side's RAM setting
			jp ntc_bk_land		; #0046: main RAM switched in
ntc_bk_land:
			ld sp, (ntc_bk_sp)
			ret				; to where main RAM handed over
			ASSERT ntc_bk_out == #0044, "the bank switch must be at #0044"
ntc_start2:
			di
			ld (ntc_csp), sp
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld ix, ntc_go
			jp ntc_plat_irqon		; interrupt handler for normal mode
ntc_go:
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:
			dw kw_scrinit		; mode 1, ROMs off, clear screen

			; 1: n = 10 : m = -3
			dw kw_ltov, 10, var_n
			dw kw_ltov, -3, var_m

			; 2: FOR i = 1 TO 10 : NEXT
			dw kw_ltov, 1, var_i
for1_t:
			dw kw_next1l_n, var_i, 10, for1_t
for1_e:

			; 3: PRINT "a"; i
			dw kw_printzoscii
			dw glyph_61, 0		; "a"
			dw kw_printint, var_i
			dw kw_printnl

			; 4: FOR i = 1 TO n : s = s + i : NEXT : PRINT "b"; s; i
			dw kw_ltov, 1, var_i
			dw kw_vtov, var_n, for2_l
			dw kw_forupv_n, var_i, for2_l, for2_e
for2_t:
			dw kw_add, var_s, var_i, var_s
			dw kw_next1v_n, var_i, for2_l, for2_t
for2_e:
			dw kw_printzoscii
			dw glyph_62, 0		; "b"
			dw kw_printint, var_s
			dw kw_printint, var_i
			dw kw_printnl

			; 5: FOR i = n TO 1 STEP -1 : PRINT i; : NEXT : PRINT
			dw kw_vtov, var_n, var_i
			dw kw_fordnl_n, var_i, 1, for3_e
for3_t:
			dw kw_printint, var_i
			dw kw_nextdnl_n, var_i, -1, 1, for3_t
for3_e:
			dw kw_printnl

			; 6: FOR i = 1 TO n STEP 3 : PRINT i; : NEXT : PRINT
			dw kw_ltov, 1, var_i
			dw kw_vtov, var_n, for4_l
			dw kw_forupv_n, var_i, for4_l, for4_e
for4_t:
			dw kw_printint, var_i
			dw kw_nextupv_n, var_i, 3, for4_l, for4_t
for4_e:
			dw kw_printnl

			; 7: FOR i = 10 TO m STEP -4 : PRINT i; " "; : NEXT : PRINT
			dw kw_ltov, 10, var_i
			dw kw_vtov, var_m, for5_l
			dw kw_fordnv_n, var_i, for5_l, for5_e
for5_t:
			dw kw_printint, var_i
			dw kw_printzoscii
			dw glyph_20, 0		; " "
			dw kw_nextdnv_n, var_i, -4, for5_l, for5_t
for5_e:
			dw kw_printnl

			; 8: FOR i = 5 TO 1 : PRINT "x" : NEXT : PRINT "c"; i
			dw kw_ltov, 5, var_i
			dw for6_e_go
for6_t:
			dw kw_printzoscii
			dw glyph_78, 1, 0		; "x\n"
			dw kw_next1l_n, var_i, 1, for6_t
for6_e:
			dw kw_printzoscii
			dw glyph_63, 0		; "c"
			dw kw_printint, var_i
			dw kw_printnl

			; 9: FOR i = n TO 1 : PRINT "x" : NEXT : PRINT "d"; i
			dw kw_vtov, var_n, var_i
			dw kw_forupl_n, var_i, 1, for7_e
for7_t:
			dw kw_printzoscii
			dw glyph_78, 1, 0		; "x\n"
			dw kw_next1l_n, var_i, 1, for7_t
for7_e:
			dw kw_printzoscii
			dw glyph_64, 0		; "d"
			dw kw_printint, var_i
			dw kw_printnl

			; 10: FOR i = m TO -1 : PRINT i; : NEXT : PRINT
			dw kw_vtov, var_m, var_i
			dw kw_forupl_n, var_i, -1, for8_e
for8_t:
			dw kw_printint, var_i
			dw kw_next1l_n, var_i, -1, for8_t
for8_e:
			dw kw_printnl

			; 11: FOR i = 254 TO 258 : PRINT i; " "; : NEXT : PRINT
			dw kw_ltov, 254, var_i
for9_t:
			dw kw_printint, var_i
			dw kw_printzoscii
			dw glyph_20, 0		; " "
			dw kw_next1l_n, var_i, 258, for9_t
for9_e:
			dw kw_printnl

			; 12: FOR i = -2 TO 2 : PRINT i; " "; : NEXT : PRINT
			dw kw_ltov, -2, var_i
for10_t:
			dw kw_printint, var_i
			dw kw_printzoscii
			dw glyph_20, 0		; " "
			dw kw_next1l_n, var_i, 2, for10_t
for10_e:
			dw kw_printnl

			; 13: st = 2 : FOR i = 1 TO 6 STEP st : PRINT i; : NEXT : PRINT
			dw kw_ltov, 2, var_st
			dw kw_ltov, 1, var_i
			dw kw_vtov, var_st, for11_s
			dw kw_ltov, 6, for11_l
			dw kw_forentry_n, var_i, for11_s, for11_l, for11_e
for11_t:
			dw kw_printint, var_i
			dw kw_fornext_n, var_i, for11_s, for11_l, for11_t
for11_e:
			dw kw_printnl
			dw kw_stop

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

for6_e_go:			ld sp, for6_e
			jp ntc_xn

; ============================================================
; Variables
; ============================================================

var_n:			dw 0
var_m:			dw 0
var_i:			dw 0
for2_l:			dw 0
var_s:			dw 0
for4_l:			dw 0
for5_l:			dw 0
var_st:			dw 0
for11_s:			dw 0
for11_l:			dw 0

; ============================================================
; ZOSCII glyphs - each points at its 8 byte bitmap in ntc_font
; ============================================================

glyph_20			equ ntc_font + 0		; " "
glyph_61			equ ntc_font + 520		; "a"
glyph_62			equ ntc_font + 528		; "b"
glyph_63			equ ntc_font + 536		; "c"
glyph_64			equ ntc_font + 544		; "d"
glyph_78			equ ntc_font + 704		; "x"

; ============================================================
; Keyword library (used)
; ============================================================

;## ntc_data @shared ntc_d_nmode
; ------------------------------------------------------------
; Scratch space: the core every program has (with ntc_d_nmode). The rest of
; the run time's variables are @data sections, each linked only when a
; linked section's code names one of its labels (no header lists them).
; They stay in this order: the keyword ROM's registry keeps each variable's
; address (a Library: ROM program has them as fixed addresses)
; ------------------------------------------------------------
ntc_next:		ret				; IX target that continues the thread
ntc_csp:		dw 0			; caller SP, for kw_stop (and the normal mode stack)
ntc_ip:			dw 0			; normal mode: thread position while out of the thread

;## ntc_d_ticks @data
ntc_ticks:		dw 0			; interrupt count (normal mode, platform handler)

;## ntc_d_nmode @data
ntc_nmode:		db 0			; 1 = running in normal mode (waits let interrupts in)

;## ntc_d_lead @data
ntc_lead:		db 0			; printint: digit seen

;## ntc_d_sptr @data
ntc_sptr:		dw 0			; printbuf: text pointer

;## ntc_d_hook @data
ntc_hookon:		db 0			; 1 = the Interrupt hook may run (set, and not running now)
ntc_hookset:	db 0			; 1 = an Interrupt hook is set
ntc_hookpend:	db 0			; 1 = an interrupt came, the hook runs at the next safe point
ntc_hook:		dw 0			; the hook Sub's call stub

;## ntc_d_numbuf @data
ntc_numbuf:		ds 14			; printint / long print: digits (+ spaces for Option VBPrint)

;## kw_stop ntc_data ntc_plat_exit @shared
kw_stop:
			ld ix, ntc_stop_back
			jp ntc_plat_exit
ntc_stop_back:
			ld sp, (ntc_csp)
			ei
			ret

;## ntc_xn ntc_data @shared
; normal mode "next": every normal mode keyword ends here (its ret
; became jp ntc_xn). Thread position to ntc_ip, real stack, one
; instruction with interrupts on, then back into the thread.
ntc_xn:
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ei
			nop					; an interrupt can be taken here
			di
			ld sp, (ntc_ip)
			ret

;## ntc_for_jump (normal mode copy)
; tails for the FOR / NEXT keywords. DE = var value, HL = limit,
; SP = thread at the label word. Signed compare by flipping bit 15.
; ntc_for_gt: jump to the label if var > limit, else skip it
ntc_for_gt_n:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			or a
			sbc hl, de			; limit - var, carry = var > limit
			pop hl
			jp nc, ntc_xn
			ld sp, hl
			jp ntc_xn
; ntc_for_lt: jump to the label if var < limit, else skip it
ntc_for_lt_n:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			ex de, hl
			or a
			sbc hl, de			; var - limit, carry = var < limit
			pop hl
			jp nc, ntc_xn
			ld sp, hl
			jp ntc_xn
; ntc_for_le: jump to the label if var <= limit (loop again). A not 0: the
; step took var past 32767 (or -32768): the loop ends (ntc_for_ge too)
ntc_for_le_n:
			or a
			jr nz, ntc_for_end_n
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			or a
			sbc hl, de			; limit - var, no carry = var <= limit
			pop hl
			jp c, ntc_xn
			ld sp, hl
			jp ntc_xn
; ntc_for_ge: jump to the label if var >= limit (loop again)
ntc_for_ge_n:
			or a
			jr nz, ntc_for_end_n
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			ex de, hl
			or a
			sbc hl, de			; var - limit, no carry = var >= limit
			pop hl
			jp c, ntc_xn
			ld sp, hl
			jp ntc_xn
ntc_for_end_n:
			pop hl
			jp ntc_xn

;## kw_forupl (normal mode copy) ntc_for_jump
;kw_forupl, <var>, <literal limit>, <endlabel>
;  FOR entry, counting up: skip the loop if var > limit
kw_forupl_n:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			jp ntc_for_gt_n

;## kw_forupv (normal mode copy) ntc_for_jump
;kw_forupv, <var>, <limit var>, <endlabel>
kw_forupv_n:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			jp ntc_for_gt_n

;## kw_fordnl (normal mode copy) ntc_for_jump
;kw_fordnl, <var>, <literal limit>, <endlabel>
;  FOR entry, counting down: skip the loop if var < limit
kw_fordnl_n:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			jp ntc_for_lt_n

;## kw_fordnv (normal mode copy) ntc_for_jump
;kw_fordnv, <var>, <limit var>, <endlabel>
kw_fordnv_n:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			jp ntc_for_lt_n

;## kw_next1l (normal mode copy) ntc_for_jump
;kw_next1l, <var>, <literal limit>, <toplabel>
;  NEXT for STEP 1: inc var, back to the top while var <= limit
kw_next1l_n:
			pop hl
			inc (hl)
			ld e, (hl)
			inc hl
			jr nz, ntc_n1l_nc_n
			inc (hl)
ntc_n1l_nc_n:
			ld d, (hl)
			pop hl
			ld a, d					; A = #FF when it went past 32767 (#8000)
			xor #80
			or e
			sub 1
			sbc a, a
			jp ntc_for_le_n

;## kw_next1v (normal mode copy) ntc_for_jump
;kw_next1v, <var>, <limit var>, <toplabel>
kw_next1v_n:
			pop hl
			inc (hl)
			ld e, (hl)
			inc hl
			jr nz, ntc_n1v_nc_n
			inc (hl)
ntc_n1v_nc_n:
			ld d, (hl)
			pop hl
			ld c, (hl)
			inc hl
			ld h, (hl)
			ld l, c
			ld a, d					; A = #FF when it went past 32767 (#8000)
			xor #80
			or e
			sub 1
			sbc a, a
			jp ntc_for_le_n

;## ntc_nextadd
; var += literal step. Pops var and step. Leaves DE = new value, A = #FF when
; it went past 32767 or -32768 (the loop ends), else 0.
ntc_nextadd:
			pop hl				; var
			pop bc				; step
			ld e, (hl)
			inc hl
			ld d, (hl)
			ex de, hl
			or a
			adc hl, bc			; P/V = past the end of the Integers
			ex de, hl			; DE = new value
			ld (hl), d
			dec hl
			ld (hl), e
			ld a, 0
			jp po, ntc_na_ok
			dec a
ntc_na_ok:
			jp (ix)

;## kw_nextupv (normal mode copy) ntc_nextadd ntc_for_jump
;kw_nextupv, <var>, <literal step>, <limit var>, <toplabel>
kw_nextupv_n:
			ld ix, ntc_nuv_back_n
			jp ntc_nextadd
ntc_nuv_back_n:
			pop hl
			ld c, (hl)
			inc hl
			ld h, (hl)
			ld l, c
			jp ntc_for_le_n

;## kw_nextdnl (normal mode copy) ntc_nextadd ntc_for_jump
;kw_nextdnl, <var>, <literal step>, <literal limit>, <toplabel>
;  NEXT for a negative STEP: add, back to the top while var >= limit
kw_nextdnl_n:
			ld ix, ntc_ndl_back_n
			jp ntc_nextadd
ntc_ndl_back_n:
			pop hl
			jp ntc_for_ge_n

;## kw_nextdnv (normal mode copy) ntc_nextadd ntc_for_jump
;kw_nextdnv, <var>, <literal step>, <limit var>, <toplabel>
kw_nextdnv_n:
			ld ix, ntc_ndv_back_n
			jp ntc_nextadd
ntc_ndv_back_n:
			pop hl
			ld c, (hl)
			inc hl
			ld h, (hl)
			ld l, c
			jp ntc_for_ge_n

;## kw_forentry (normal mode copy)
;kw_forentry, <var>, <stepvar>, <limvar>, <endlabel>
;  skip the loop if var is already past lim for the step sign
kw_forentry_n:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld b, (hl)
			inc hl
			ld b, (hl)
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			bit 7, b
			jr nz, ntc_fe_neg_n
			or a
			sbc hl, de
			pop hl
			jp nc, ntc_xn
			ld sp, hl
			jp ntc_xn
ntc_fe_neg_n:
			ex de, hl
			or a
			sbc hl, de
			pop hl
			jp nc, ntc_xn
			ld sp, hl
			jp ntc_xn

;## kw_fornext (normal mode copy)
;kw_fornext, <var>, <stepvar>, <limvar>, <toplabel>
;  var += step, loop back while var has not passed lim
kw_fornext_n:
			pop ix
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld l, (ix+0)
			ld h, (ix+1)
			or a
			adc hl, de			; P/V = past 32767 or -32768: the loop ends
			ld (ix+0), l
			ld (ix+1), h
			jp pe, ntc_fn_end_n
			ld b, d
			ex de, hl
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			bit 7, b
			jr nz, ntc_fn_neg_n
			or a
			sbc hl, de
			pop hl
			jp c, ntc_xn
			ld sp, hl
			jp ntc_xn
ntc_fn_neg_n:
			ex de, hl
			or a
			sbc hl, de
			pop hl
			jp c, ntc_xn
			ld sp, hl
			jp ntc_xn
ntc_fn_end_n:
			pop hl
			pop hl
			jp ntc_xn

; ============================================================
; Assignment
; ============================================================

;## kw_ltov
;kw_ltov, <literal>, <destvar>
kw_ltov:
			pop de
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_vtov
;kw_vtov, <sourcevar>, <destvar>
kw_vtov:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_add
;kw_add, <var1>, <var2>, <destvar>
kw_add:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			add hl, de
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## ntc_printbuf ntc_data ntc_plat_screen
; print the 0 terminated ASCII text at (ntc_sptr), then ret (thread)
ntc_printbuf:
			ld hl, (ntc_sptr)
			ld a, (hl)
			or a
			ret z
			inc hl
			ld (ntc_sptr), hl
			ld ix, ntc_printbuf
			jp ntc_plat_putc

;## kw_printzoscii ntc_data ntc_font ntc_plat_screen
;kw_printzoscii / dw glyph, glyph, ..., 0  - ZOSCII text inline in the thread
;  each word points at an 8 byte glyph bitmap. 1 = newline, 0 = end (only those two:
;  a program at #0040 can have glyphs below #0100)
kw_printzoscii:
			pop de
			ld a, d
			or a
			jr nz, ntc_pz_glyph
			ld a, e
			cp 2
			jr c, ntc_pz_ctl
ntc_pz_glyph:
			ld ix, kw_printzoscii
			jp ntc_plat_putglyph
ntc_pz_ctl:
			or a
			ret z
			ld ix, kw_printzoscii
			jp ntc_plat_newline

;## ntc_itoa ntc_data
; HL = signed value, DE = buffer: writes the digits and a 0 (DE ends on
; the 0). jp (ix) back. Uses A, BC, IY.
ntc_itoa:
			bit 7, h
			jr z, ntc_ia_pos
			ld a, '-'
			ld (de), a
			inc de
			xor a
			sub l
			ld l, a
			sbc a, a
			sub h
			ld h, a
ntc_ia_pos:
			xor a
			ld (ntc_lead), a
			ld iy, ntc_pow10
ntc_ia_pow:
			ld c, (iy+0)
			ld b, (iy+1)
			ld a, b
			or c
			jr z, ntc_ia_last
			ld a, '0' - 1
ntc_ia_sub:
			inc a
			and a
			sbc hl, bc
			jr nc, ntc_ia_sub
			add hl, bc
			cp '0'
			jr nz, ntc_ia_out
			ld b, a
			ld a, (ntc_lead)
			or a
			ld a, b
			jr z, ntc_ia_skip
ntc_ia_out:
			ld (de), a
			inc de
			ld a, 1
			ld (ntc_lead), a
ntc_ia_skip:
			inc iy
			inc iy
			jr ntc_ia_pow
ntc_ia_last:
			ld a, l
			add a, '0'
			ld (de), a
			inc de
			xor a
			ld (de), a
			jp (ix)
ntc_pow10:		dw 10000, 1000, 100, 10, 0

;## kw_printint ntc_printbuf ntc_itoa
;kw_printint, <var>  - signed decimal
kw_printint:
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ld de, ntc_numbuf
			ld ix, ntc_pi_done
			jp ntc_itoa
ntc_pi_done:
			ld hl, ntc_numbuf
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## kw_printnl ntc_data ntc_plat_screen
;kw_printnl
kw_printnl:
			ld ix, ntc_next
			jp ntc_plat_newline

;## kw_scrinit ntc_data ntc_plat_screen
;kw_scrinit  - first word of any program that prints or reads keys:
;  mode 1, ROMs off, clear screen
kw_scrinit:
			ld a, 1
			ld ix, ntc_next
			jp ntc_plat_mode

;## ntc_font
; 8x8 font buffer, chars 32-126, 8 bytes each, bit 7 = leftmost pixel.
; The platform fills it at start: the CPC copies its own font from the
; lower ROM (#3900), so text looks like the CPC's.
; glyph for char c = ntc_font + (c - 32) * 8
ntc_font:		ds 95 * 8

; ============================================================
; Platform class capabilities
; ============================================================

;## ntc_plat_data
ntc_curx:		db 0			; cursor column (0 based)
ntc_cury:		db 0			; cursor row (0 based)
ntc_smode:		db 1			; screen mode
ntc_sinit:		db 0			; 1 once the screen is set up
ntc_sbpc:		db 2			; bytes per char  \
ntc_scols:		db 40			; columns          | from ntc_modetab
ntc_smask:		db #F0			; pen 1 pixel mask |
ntc_sshift:		db 4			; glyph bits/byte /
ntc_pgstk:		ds 32			; putglyph: the stack an interrupt uses between characters
ntc_pgstk_top:
ntc_noadv:		db 0			; 1 = draw without moving the cursor
ntc_wrapped:	db 0			; 1 = the last character wrapped to the next line
ntc_pgrow:		db 0			; draw / scroll counter
ntc_pgaddr:		dw 0			; draw / scroll address
ntc_klink:		dw 0			; return for ntc_plat_getkey
ntc_kidx:		db 0			; key index found by the scan
ntc_kcur:		ds 10			; matrix this scan (0 = pressed)
ntc_kprev:		db #FF, #FF, #FF, #FF, #FF, #FF, #FF, #FF, #FF, #FF
ntc_irqset:		db 0			; 1 = our interrupt handler is at #38
ntc_irqold:		ds 3			; the 3 bytes it replaced
ntc_irqhl:		dw 0			; handler scratch
ntc_irqv:		dw 0			; interrupt classes' counting (ntc_isl_tick), 0 = none
	IF NTC_ROMLIB
ntc_uroff:		db 0			; (ROM) 1 = the upper ROM is off while the screen is read
	ENDIF
ntc_modetab:	db 4, 20, #C0, 2		; mode 0
				db 2, 40, #F0, 4		; mode 1
				db 1, 80, #FF, 8		; mode 2

; (ntc_plat_scroll, ntc_plat_cls: their own section - the ROM runs them from RAM)

;## ntc_plat_screen ntc_plat_data ntc_font ntc_data ntc_plat_scroll @shared
; ------------------------------------------------------------
; ntc_plat_putc - A = character 32-126 (others print as ?), draw it
; ------------------------------------------------------------
ntc_plat_putc:
			sub 32
			jr c, ntc_pc_bad
			cp 95
			jr c, ntc_pc_ok
ntc_pc_bad:
			ld a, '?' - 32
ntc_pc_ok:
			ld l, a
			ld h, 0
			add hl, hl
			add hl, hl
			add hl, hl
			ld de, ntc_font
			add hl, de
			ex de, hl
			; fall into ntc_plat_putglyph

; ------------------------------------------------------------
; ntc_plat_putglyph - DE = 8 byte glyph, draw at the cursor, move on
; ------------------------------------------------------------
ntc_plat_putglyph:
			ld a, (ntc_cury)
			ld l, a
			ld h, 0
			add hl, hl
			add hl, hl
			add hl, hl
			add hl, hl
			ld b, h
			ld c, l
			add hl, hl
			add hl, hl
			add hl, bc			; HL = row * 80
			ld a, (ntc_sbpc)
			ld b, a
			ld a, (ntc_curx)
			ld c, a
			xor a
ntc_pg_mul:
			add a, c
			djnz ntc_pg_mul		; A = column * bytes per char
			ld c, a
			ld b, #C0
			add hl, bc			; HL = #C000 + row*80 + col*bpc
			ld a, (ntc_sbpc)		; mode 1 (2 bytes a row) and 2 (1 byte): their own loops
			cp 2
			jr z, ntc_pg_m1
			dec a
			jr z, ntc_pg_m2
			ld b, 8					; mode 0: 4 bytes a row, 2 pixels each (pen 1: bits 7, 6)
ntc_pg_m0lp:
			ld a, (de)
			inc de
			ld c, a
			and #C0
			ld (hl), a
			inc hl
			ld a, c
			rlca
			rlca
			ld c, a
			and #C0
			ld (hl), a
			inc hl
			ld a, c
			rlca
			rlca
			ld c, a
			and #C0
			ld (hl), a
			inc hl
			ld a, c
			rlca
			rlca
			and #C0
			ld (hl), a
			dec hl
			dec hl
			dec hl
			ld a, h
			add a, 8
			ld h, a
			djnz ntc_pg_m0lp
			jr ntc_pg_drawn
ntc_pg_m1:
			ld b, 8
ntc_pg_m1lp:
			ld a, (de)				; pen 1: pixels 0-3 in the high nibble, 4-7 next
			inc de
			ld c, a
			and #F0
			ld (hl), a
			inc hl
			ld a, c
			rlca
			rlca
			rlca
			rlca
			and #F0
			ld (hl), a
			dec hl
			ld a, h
			add a, 8
			ld h, a
			djnz ntc_pg_m1lp
			jr ntc_pg_drawn
ntc_pg_m2:
			ld b, 8
ntc_pg_m2lp:
			ld a, (de)
			inc de
			ld (hl), a
			ld a, h
			add a, 8
			ld h, a
			djnz ntc_pg_m2lp
ntc_pg_drawn:
			ld a, (ntc_nmode)		; normal mode: a waiting interrupt gets in after each
			or a					; character (drawing text is long), on a stack of its own
			jr z, ntc_pg_adv		; (SP may be the thread or the real stack here)
			ld (ntc_pgaddr), sp
			ld sp, ntc_pgstk_top
			ei
			nop
			di
			ld sp, (ntc_pgaddr)
ntc_pg_adv:
			ld a, (ntc_noadv)
			or a
			jr nz, ntc_pg_noadv
			ld a, (ntc_scols)
			ld b, a
			ld a, (ntc_curx)
			inc a
			ld (ntc_curx), a
			cp b
			jr z, ntc_pg_wrap
			xor a
			ld (ntc_wrapped), a
			jp (ix)
ntc_pg_wrap:
			ld a, 1				; wrapped: a new line straight after does nothing
			ld (ntc_wrapped), a
			jr ntc_nl_do
ntc_pg_noadv:
			xor a
			ld (ntc_noadv), a
			jp (ix)

; ------------------------------------------------------------
; ntc_plat_newline - column 0, next row, scroll at the bottom. Straight
; after a wrap at the last column it does nothing (as the firmware does)
; ------------------------------------------------------------
ntc_plat_newline:
			ld a, (ntc_wrapped)
			or a
			jr z, ntc_nl_do
			xor a
			ld (ntc_wrapped), a
			jp (ix)
ntc_nl_do:
			xor a
			ld (ntc_curx), a
			ld a, (ntc_cury)
			inc a
			cp 25
			jp nc, ntc_plat_scroll
			ld (ntc_cury), a
			jp (ix)

;## ntc_plat_mode @unit ntc_plat_screen ntc_plat_data ntc_font ntc_data ntc_plat_scroll @shared
; ------------------------------------------------------------
; ntc_plat_mode - A = mode (0-2, 3 = 2). Gate array mode with both
; ROMs off, set text layout, clear screen
; ------------------------------------------------------------
ntc_plat_mode:
			cp 3
			jr c, ntc_md_ok
			ld a, 2
ntc_md_ok:
			ld (ntc_smode), a
			ld a, (ntc_sinit)
			or a
			jr nz, ntc_md_set
			; the first time: copy the CPC's own font (lower ROM, chars 32-126 at
			; #3900) into ntc_font. The copy runs from #C000 (screen RAM, cleared
			; just after), because the program itself can sit under the lower ROM
		IF NTC_ROMLIB
			jp ntc_fontcopy		; (ROM: it runs here - the lower ROM goes on, this one stays on)
		ELSE
			ld hl, ntc_fontcopy
			ld de, #C000
			ld bc, ntc_fontcopy_end - ntc_fontcopy
			ldir
			jp #C000
		ENDIF
ntc_md_set:
			ld a, (ntc_smode)
			ld c, a
		IF NTC_ROMLIB
			or #84				; (ROM: the upper ROM on)
		ELSE
			or #8C
		ENDIF
			ld b, #7F
			out (c), a
			ld a, 1
			ld (ntc_sinit), a
			ld a, c
			add a, a
			add a, a
			ld c, a
			ld b, 0
			ld hl, ntc_modetab
			add hl, bc
			ld de, ntc_sbpc
			ld bc, 4
			ldir
			jp ntc_plat_cls

; copied to #C000 and run there (no jumps inside: it runs at any address)
ntc_fontcopy:
		IF NTC_ROMLIB
			ld bc, #7F80		; lower ROM on, upper ROM (this one) on
		ELSE
			ld bc, #7F88		; lower ROM on, upper ROM off
		ENDIF
			out (c), c
			ld hl, #3900		; the firmware's character matrices, from char 32
			ld de, ntc_font
			ld bc, 95 * 8
			ldir
		IF NTC_ROMLIB
			ld bc, #7F84		; lower ROM off again
		ELSE
			ld bc, #7F8C		; both ROMs off again
		ENDIF
			out (c), c
			jp ntc_md_set
ntc_fontcopy_end:

;## ntc_plat_scroll ntc_plat_data ntc_data @shared @romram
; ------------------------------------------------------------
; ntc_plat_scroll - move rows 1-24 up one, clear row 24
; ------------------------------------------------------------
ntc_plat_scroll:
			ld a, 24
			ld (ntc_cury), a
			ld a, (ntc_nmode)		; normal mode: interrupts in during the long copy
			or a
			jr z, ntc_sc_open
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ei
ntc_sc_open:
		IF NTC_ROMLIB
			ld a, 1				; (ROM: the upper ROM off while the screen is read;
			ld (ntc_uroff), a	; the interrupt handler turns it on for its calls)
			ld a, (ntc_smode)
			or #8C
			ld b, #7F
			out (c), a
		ENDIF
			ld hl, #C000
			ld a, 8
ntc_sc_line:
			ld (ntc_pgrow), a
			ld (ntc_pgaddr), hl
			ld d, h
			ld e, l
			ld bc, 80
			add hl, bc
			ld bc, 24 * 80
			ldir
			ld h, d
			ld l, e
			ld (hl), 0
			inc de
			ld bc, 79
			ldir
			ld hl, (ntc_pgaddr)
			ld bc, #800
			add hl, bc
			ld a, (ntc_pgrow)
			dec a
			jr nz, ntc_sc_line
			di
		IF NTC_ROMLIB
			ld a, (ntc_smode)	; (ROM: the upper ROM on again)
			or #84
			ld b, #7F
			out (c), a
			xor a
			ld (ntc_uroff), a
		ENDIF
			ld a, (ntc_nmode)
			or a
			jr z, ntc_sc_close
			ld sp, (ntc_ip)
ntc_sc_close:
			jp (ix)

; ------------------------------------------------------------
; ntc_plat_cls - clear screen memory, cursor home
; ------------------------------------------------------------
ntc_plat_cls:
			ld a, (ntc_nmode)		; normal mode: interrupts in during the long copy
			or a
			jr z, ntc_cl_open
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ei
ntc_cl_open:
		IF NTC_ROMLIB
			ld a, 1				; (ROM: the upper ROM off - the fill reads the screen back)
			ld (ntc_uroff), a
			ld a, (ntc_smode)
			or #8C
			ld b, #7F
			out (c), a
		ENDIF
			ld hl, #C000
			ld de, #C001
			ld bc, #3FFF
			ld (hl), 0
			ldir
			di
		IF NTC_ROMLIB
			ld a, (ntc_smode)	; (ROM: the upper ROM on again)
			or #84
			ld b, #7F
			out (c), a
			xor a
			ld (ntc_uroff), a
		ENDIF
			ld a, (ntc_nmode)
			or a
			jr z, ntc_cl_close
			ld sp, (ntc_ip)
ntc_cl_close:
			xor a
			ld (ntc_wrapped), a
			ld (ntc_curx), a
			ld (ntc_cury), a
			jp (ix)

;## ntc_plat_irq ntc_plat_data ntc_data ntc_plat_irqh @shared
; ------------------------------------------------------------
; ntc_plat_irqon - put the interrupt handler at #38 (IM 1)
; ------------------------------------------------------------
ntc_plat_irqon:
			ld hl, (#0038)
			ld (ntc_irqold), hl
			ld a, (#003A)
			ld (ntc_irqold + 2), a
			ld a, #C3			; jp ntc_irq
			ld (#0038), a
			ld hl, ntc_irq
			ld (#0039), hl
			ld a, 1
			ld (ntc_irqset), a
			jp (ix)

;## ntc_plat_irqh ntc_plat_data ntc_data @shared @romram
; the handler: runs on the real stack, between keywords. Counts ticks
; (300 a second). AF goes to AF', HL to RAM; interrupt classes' counting
; (ntc_irqv) is a call, keeping the other registers.
ntc_irq:
			ex af, af'
			ld (ntc_irqhl), hl
			ld hl, (ntc_ticks)
			inc hl
			ld (ntc_ticks), hl
			ld a, (ntc_hookon)	; an Interrupt hook: run it at the next safe point
			or a
			jr z, ntc_irq_nohook
			ld (ntc_hookpend), a
ntc_irq_nohook:
			ld hl, (ntc_irqv)		; interrupt classes (Option Class Interrupt): count them
			ld a, h
			or l
		IF NTC_ROMLIB
			call nz, ntc_irq_rom	; (the handler runs on the real stack)
		ELSE
			call nz, ntc_irq_jp		; (the handler runs on the real stack)
		ENDIF
			ld hl, (ntc_irqhl)
			ex af, af'
			ei
			ret
ntc_irq_jp:
			jp (hl)
		IF NTC_ROMLIB
; (ROM) the counting is in the main ROM of the set: the upper ROM on and the
; main ROM selected for the call (the screen code may have the upper ROM off,
; a far routine may have another ROM of the set in), then both as they were
ntc_irq_rom:
			push bc
			ld a, (ntc_smode)
			or #84
			ld b, #7F
			out (c), a
			ld bc, (ntc_rx_s0)		; B = #DF, C = the main ROM's slot
			out (c), c
			call ntc_irq_jp
			ld bc, (ntc_rx_cur)		; the ROM that was in
			out (c), c
			ld a, (ntc_uroff)
			or a
			jr z, ntc_irq_ron
			ld a, (ntc_smode)
			or #8C
			ld b, #7F
			out (c), a
ntc_irq_ron:
			pop bc
			ret
		ENDIF

;## ntc_plat_exit ntc_plat_data
; ------------------------------------------------------------
; ntc_plat_exit - before returning to the caller: interrupt handler
; out, upper ROM back on (lower off) if the screen was set up
; ------------------------------------------------------------
ntc_plat_exit:
			ld bc, #7FC0		; RAM setting back to plain (a Memory page may be in #4000)
			out (c), c
			ld a, (ntc_irqset)
			or a
			jr z, ntc_ex_rom
			ld hl, (ntc_irqold)
			ld (#0038), hl
			ld a, (ntc_irqold + 2)
			ld (#003A), a
			xor a
			ld (ntc_irqset), a
ntc_ex_rom:
			ld a, (ntc_sinit)
			or a
			jr z, ntc_ex_done
			ld a, (ntc_smode)
			or #84
			ld b, #7F
			out (c), a
ntc_ex_done:
			jp (ix)


ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bssfrom	equ ntc_end
ntc_bss		equ ntc_bssfrom
ntc_bss_size	equ 0
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
ntc_memtab	equ ntc_free		; the Memory class's tables
